CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');

CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;

CREATE TABLE public.profiles (id uuid PRIMARY KEY,email text,first_name text,last_name text,display_name text,bio text,phone text,gender text,age integer,timezone text NOT NULL DEFAULT 'UTC',avatar_url text,onboarded boolean NOT NULL DEFAULT false,onboarded_at timestamptz,last_seen_at timestamptz,sign_in_count integer NOT NULL DEFAULT 0,avg_study_hours numeric,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR ALL TO authenticated USING(auth.uid()=id) WITH CHECK(auth.uid()=id);

CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,role public.app_role NOT NULL DEFAULT 'user',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_roles_read_own ON public.user_roles FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role)$$;

CREATE TABLE public.app_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id),site_name text NOT NULL DEFAULT 'Chronodeck Study OS',tagline text NOT NULL DEFAULT 'Study smarter, every day',support_email text,banner_text text,ai_enabled boolean NOT NULL DEFAULT true,manual_log_enabled boolean NOT NULL DEFAULT true,landing_enabled boolean NOT NULL DEFAULT true,maintenance_note text,signup_enabled boolean NOT NULL DEFAULT true,google_auth_enabled boolean NOT NULL DEFAULT true,one_tap_enabled boolean NOT NULL DEFAULT true,email_auth_enabled boolean NOT NULL DEFAULT true,onboarding_require_subjects boolean NOT NULL DEFAULT true,default_daily_goal_hours numeric NOT NULL DEFAULT 4,default_weekly_goal_hours numeric NOT NULL DEFAULT 25,announcement_level text NOT NULL DEFAULT 'info',accent_color text NOT NULL DEFAULT '#2563eb',favicon_url text,logo_url text,push_enabled boolean NOT NULL DEFAULT true,avatar_upload_enabled boolean NOT NULL DEFAULT true,android_min_version text,android_latest_version text,android_update_url text,android_force_update boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.app_settings TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.app_settings TO authenticated; GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY app_settings_read ON public.app_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY app_settings_admin_write ON public.app_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));

CREATE TABLE public.motivations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL DEFAULT 'quote',title text NOT NULL DEFAULT '',body text NOT NULL DEFAULT '',author text,month smallint,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.motivations TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.motivations TO authenticated; GRANT ALL ON public.motivations TO service_role;
ALTER TABLE public.motivations ENABLE ROW LEVEL SECURITY;
CREATE POLICY motivations_read ON public.motivations FOR SELECT TO anon,authenticated USING(is_active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY motivations_admin_write ON public.motivations FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));

CREATE TABLE public.avatar_presets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,image_url text NOT NULL,sort_order integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.avatar_presets TO authenticated; GRANT ALL ON public.avatar_presets TO service_role;
ALTER TABLE public.avatar_presets ENABLE ROW LEVEL SECURITY;
CREATE POLICY avatar_read ON public.avatar_presets FOR SELECT TO authenticated USING(is_active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY avatar_admin ON public.avatar_presets FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));

CREATE TABLE public.subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,name text NOT NULL,color text NOT NULL DEFAULT '#A9C9FF',chapters jsonb NOT NULL DEFAULT '[]',weekly_target_hours numeric NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.subjects TO authenticated; GRANT ALL ON public.subjects TO service_role;
ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY; CREATE POLICY subjects_own ON public.subjects FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);

CREATE TABLE public.chapters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,subject_id uuid NOT NULL REFERENCES public.subjects(id) ON DELETE CASCADE,name text NOT NULL,position integer NOT NULL DEFAULT 0,difficulty smallint NOT NULL DEFAULT 3,estimated_minutes integer NOT NULL DEFAULT 60,total_units integer,units_done integer NOT NULL DEFAULT 0,first_pass_done boolean NOT NULL DEFAULT false,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(subject_id,name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.chapters TO authenticated; GRANT ALL ON public.chapters TO service_role;
ALTER TABLE public.chapters ENABLE ROW LEVEL SECURITY; CREATE POLICY chapters_own ON public.chapters FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);

