GRANT SELECT,INSERT,UPDATE,DELETE ON public.chapter_subtopics TO authenticated; GRANT ALL ON public.chapter_subtopics TO service_role;
ALTER TABLE public.chapter_subtopics ENABLE ROW LEVEL SECURITY; CREATE POLICY subtopics_own ON public.chapter_subtopics FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);

CREATE TABLE public.study_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,subject_id uuid REFERENCES public.subjects(id) ON DELETE SET NULL,subject_name text,chapter text,topic text,category text,kind text NOT NULL DEFAULT 'reading',notes text,started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,planned_end_at timestamptz,is_running boolean NOT NULL DEFAULT true,auto_closed boolean NOT NULL DEFAULT false,break_type text,break_started_at timestamptz,break_minutes integer NOT NULL DEFAULT 0,total_break_seconds integer NOT NULL DEFAULT 0,duration_minutes integer,duration_seconds integer,xp_earned integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),chapter_id uuid REFERENCES public.chapters(id) ON DELETE SET NULL,subtopic_id uuid REFERENCES public.chapter_subtopics(id) ON DELETE SET NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.study_sessions TO authenticated; GRANT ALL ON public.study_sessions TO service_role;
ALTER TABLE public.study_sessions ENABLE ROW LEVEL SECURITY; CREATE POLICY sessions_own ON public.study_sessions FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
