CREATE OR REPLACE FUNCTION public.touch_last_seen() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.profiles SET last_seen_at=now(),sign_in_count=sign_in_count+1 WHERE id=auth.uid(); END $$;
CREATE OR REPLACE FUNCTION public.log_reading(_kind text,_minutes integer) RETURNS public.reading_logs LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r public.reading_logs; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF; INSERT INTO public.reading_logs(user_id,kind,log_date,minutes,sittings) VALUES(auth.uid(),_kind,CURRENT_DATE,_minutes,1) ON CONFLICT(user_id,kind,log_date) DO UPDATE SET minutes=public.reading_logs.minutes+EXCLUDED.minutes,sittings=public.reading_logs.sittings+1,updated_at=now() RETURNING * INTO r; RETURN r; END $$;
CREATE OR REPLACE FUNCTION public.undo_reading(_kind text) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ BEGIN DELETE FROM public.reading_logs WHERE user_id=auth.uid() AND kind=_kind AND log_date=CURRENT_DATE; END $$;
CREATE OR REPLACE FUNCTION public.ensure_my_subject_targets() RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.subject_targets(user_id,subject_id,daily_minutes,weekly_minutes,monthly_minutes) SELECT auth.uid(),s.id,GREATEST(1,round(s.weekly_target_hours*60/7)),round(s.weekly_target_hours*60),round(s.weekly_target_hours*60*4) FROM public.subjects s WHERE s.user_id=auth.uid() ON CONFLICT(user_id,subject_id) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.set_plan_item_status(_item_id uuid,_status text) RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ BEGIN UPDATE public.daily_study_plan_items SET status=_status,skipped_at=CASE WHEN _status='skipped' THEN now() ELSE NULL END,cancelled_at=CASE WHEN _status='cancelled' THEN now() ELSE NULL END,updated_at=now() WHERE id=_item_id AND user_id=auth.uid(); RETURN 0; END $$;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role),public.touch_last_seen(),public.log_reading(text,integer),public.undo_reading(text),public.ensure_my_subject_targets(),public.set_plan_item_status(uuid,text) TO authenticated;

INSERT INTO public.app_settings(id) VALUES(true) ON CONFLICT DO NOTHING;
